import json
import re
import datetime
import html as _html

AI_PROMPT = (
    "You are condensing clinical records for a practitioner's own pre-appointment review at a healthcare clinic. "
    "Summarise only what is explicitly written in the notes given - what was done, what was noted, any follow-up "
    "the practitioner recorded themselves. Never add a clinical interpretation, a likely diagnosis, or a "
    "treatment suggestion. If there is nothing recorded, say plainly that there is nothing on file. Keep it to "
    "3-5 short factual sentences."
)
AI_HINT = '{"summary": ""}'


def read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def extract_id(link):
    if not isinstance(link, dict):
        return ""
    url = ((link.get("links") or {}).get("self")) or ""
    m = re.search(r"/(\d+)(?:$|\?)", str(url))
    return m.group(1) if m else ""


def flatten_note_content(content):
    # TreatmentNote.content is {sections: [{name, description, questions: [{name, type, answer}]}]},
    # not plain text (confirmed against docs.api.cliniko.com/openapi/treatment-note).
    content = content if isinstance(content, dict) else {}
    lines = []
    for section in (content.get("sections") or []):
        if not isinstance(section, dict):
            continue
        for q in (section.get("questions") or []):
            if not isinstance(q, dict):
                continue
            answer = q.get("answer")
            if answer in (None, "", []):
                continue
            name = q.get("name") or ""
            lines.append(((name + ": ") if name else "") + str(answer))
    return lines


def format_date(iso):
    return str(iso or "")[:10]


tomorrow = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(days=1)).date()
day_start = tomorrow.isoformat() + "T00:00:00Z"
day_end = (tomorrow + datetime.timedelta(days=1)).isoformat() + "T00:00:00Z"

practices = []
try:
    entries = api.files.list(path="PracticeManager/Practices", scope="org")
except Exception:
    entries = []
for entry in entries or []:
    fname = entry.get("name") if isinstance(entry, dict) else entry
    if not fname or not str(fname).endswith(".json"):
        continue
    slug = str(fname)[:-5]
    practice = read_json("PracticeManager/Practices/" + fname, {}) or {}
    if practice:
        practices.append({"slug": slug, "practice": practice})

practice_sections = []
for p in practices:
    business_id = str(p["practice"].get("cliniko_business_id") or "")
    if not business_id:
        continue
    try:
        result = api.connectors.invoke(
            server="cliniko-scheduling", tool="list_individual_appointments",
            args={"q": ["business_id:=" + business_id, "starts_at:>=" + day_start, "starts_at:<" + day_end], "sort": "starts_at:asc", "per_page": 50},
        )
        appts = [r for r in (result or {}).get("individual_appointments") or [] if not r.get("cancelled_at")]
    except Exception:
        appts = []

    patient_cards = []
    for appt in appts:
        patient_id = extract_id(appt.get("patient"))
        patient_name = appt.get("patient_name") or "Unknown patient"

        notes_summary = "No treatment notes on file."
        if patient_id:
            try:
                notes_result = api.connectors.invoke(
                    server="cliniko-clinical", tool="list_treatment_notes",
                    args={"q": ["patient_id:=" + patient_id], "sort": "created_at:desc", "per_page": 5},
                )
                all_notes = (notes_result or {}).get("treatment_notes") or []
            except Exception:
                all_notes = []
            # Draft notes aren't a finalized clinical record yet - skip them, same reasoning as never
            # guessing a missing value: don't present unreviewed content as settled fact.
            finalized = [n for n in all_notes if n.get("finalized_at") and not n.get("draft")][:3]
            lines = []
            for n in finalized:
                flat = flatten_note_content(n.get("content"))
                if flat:
                    lines.append(format_date(n.get("created_at")) + " - " + "; ".join(flat))
            if lines:
                try:
                    drafted = api.ai.extract(prompt=AI_PROMPT, input="\n".join(lines)[:6000], schema_hint=AI_HINT)
                except Exception:
                    drafted = {}
                notes_summary = (drafted or {}).get("summary") or "\n".join(lines)[:500]

        attachments_line = "None on file."
        if patient_id:
            try:
                att_result = api.connectors.invoke(
                    server="cliniko-clinical", tool="list_patient_attachments",
                    args={"q": ["patient_id:=" + patient_id], "sort": "created_at:desc", "per_page": 5},
                )
                atts = (att_result or {}).get("patient_attachments") or []
            except Exception:
                atts = []
            if atts:
                attachments_line = "; ".join(
                    (str(a.get("title") or a.get("content_type") or "file")) + " (" + format_date(a.get("created_at")) + ")"
                    for a in atts
                )

        alerts_lines = []
        if patient_id:
            try:
                alert_result = api.connectors.invoke(
                    server="cliniko-clinical", tool="list_medical_alerts", args={"q": ["patient_id:=" + patient_id]},
                )
                alerts = (alert_result or {}).get("medical_alerts") or []
            except Exception:
                alerts = []
            # Medical alerts are shown verbatim, never paraphrased - they're the one thing here where
            # condensing risks losing something safety-relevant.
            alerts_lines = [str(a.get("description") or a.get("title") or a) for a in alerts]

        patient_cards.append({
            "time": str(appt.get("starts_at") or ""),
            "patient_name": patient_name,
            "notes_summary": notes_summary,
            "attachments_line": attachments_line,
            "alerts": alerts_lines,
        })

    if patient_cards:
        practice_sections.append({
            "slug": p["slug"],
            "name": p["practice"].get("name") or p["slug"],
            "reviewer_id": p["practice"].get("reviewer_id") or "",
            "patients": patient_cards,
        })

if not practice_sections:
    outcome = "no_appointments"
    artifact_url = ""
else:
    blocks = []
    for sec in practice_sections:
        cards = []
        for c in sec["patients"]:
            alerts_html = (
                "<p class='alert'><b>Medical alerts:</b> " + _html.escape("; ".join(c["alerts"])) + "</p>"
                if c["alerts"] else ""
            )
            cards.append(
                "<div class='card'><h3>" + _html.escape(c["time"]) + " - " + _html.escape(c["patient_name"]) + "</h3>"
                + alerts_html
                + "<p><b>Recent notes:</b> " + _html.escape(c["notes_summary"]) + "</p>"
                + "<p><b>Attachments:</b> " + _html.escape(c["attachments_line"]) + "</p></div>"
            )
        blocks.append("<h2>" + _html.escape(sec["name"]) + "</h2>" + "".join(cards))

    page = (
        "<!doctype html><html><head><meta charset='utf-8'><title>Pre-appointment summary " + tomorrow.isoformat() + "</title>"
        "<style>body{font:14px/1.5 system-ui,sans-serif;margin:24px;color:#1c2330}h1{font-size:20px}h2{font-size:16px;margin-top:24px}"
        ".card{border:1px solid #e3e6ec;border-radius:8px;padding:10px 14px;margin-bottom:10px}"
        ".alert{background:#fdecea;color:#9a3b20;padding:6px 10px;border-radius:6px}"
        "</style></head><body>"
        "<h1>Pre-appointment summary, " + tomorrow.isoformat() + "</h1>"
        "<p style='color:#5d6778'>Summaries only - nothing here is a clinical interpretation.</p>"
        + "".join(blocks) + "</body></html>"
    )
    saved = api.artifacts.put(
        title="Pre-appointment summary " + tomorrow.isoformat(), content=page,
        file_name="pre-appointment-summary-" + tomorrow.isoformat() + ".html", kind="document",
        mime_type="text/html", tags=["healthcare-practice-management", "pre-appointment-summary"],
    )
    artifact_url = (saved or {}).get("url") or ""
    for sec in practice_sections:
        if sec["reviewer_id"]:
            api.notify.send(
                title="Tomorrow's pre-appointment summary is ready",
                body=(str(len(sec["patients"])) + " appointment(s) for " + sec["name"] + ". " + artifact_url).strip(),
                user_ids=[sec["reviewer_id"]],
            )
    outcome = "summary_ready"
